工作目录：/home/jinsc/SDK/vela/openvela
只允许修改一个文件：
/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/ui/bicycle/src/bicycle_ui_ctl.c
不得改 vela_sifli 副本、不得改日志/其它文件、不得 commit、不要构建。

背景：Codex R4 仍判 REJECT，两点：
- [P2] 336px 总预算仍不能保证两行：按词折行会有空隙；文件名含换行符（如 `a\nb\nc.gpx`）必然 3 行。
- [P3] UTF-8 校验接受过长编码/代理码位/超范围（`C0 80`、`ED A0 80`、`F4 90 80 80`）。

R5 要求：
1. 收紧 `bicycle_ui_ctl_utf8_len()` 的合法性判定。
2. 不再只靠像素预算：用 LVGL 自己的折行结果（`lv_text_get_size()` 的高度）迭代回退文件名，直到实际排版 ≤2 行。

=== 1) 收紧 bicycle_ui_ctl_utf8_len() ===
把该函数改成（保留函数注释并补充范围检查说明）：

static size_t bicycle_ui_ctl_utf8_len(const char * s, size_t n)
{
    const unsigned char c = (unsigned char)s[n];
    size_t len;
    size_t i;

    if (c < 0x80u) {
        return 1u;
    }
    if (c < 0xC2u) {
        return 0u;              /* 续字节或过长 2 字节编码 */
    }
    if (c < 0xE0u) {
        len = 2u;
    } else if (c < 0xF0u) {
        len = 3u;
    } else if (c < 0xF5u) {
        len = 4u;
    } else {
        return 0u;              /* F5..FF 超出 Unicode 范围 */
    }

    for (i = 1u; i < len; i++) {
        const unsigned char cc = (unsigned char)s[n + i];

        if (cc == '\0' || (cc & 0xC0u) != 0x80u) {
            return 0u;
        }
    }

    if (len == 3u) {
        const unsigned char c1 = (unsigned char)s[n + 1u];

        if (c == 0xE0u && c1 < 0xA0u) {
            return 0u;          /* 过长 3 字节 */
        }
        if (c == 0xEDu && c1 >= 0xA0u) {
            return 0u;          /* UTF-16 代理区 */
        }
    } else if (len == 4u) {
        const unsigned char c1 = (unsigned char)s[n + 1u];

        if (c == 0xF0u && c1 < 0x90u) {
            return 0u;          /* 过长 4 字节 */
        }
        if (c == 0xF4u && c1 >= 0x90u) {
            return 0u;          /* > U+10FFFF */
        }
    }

    return len;
}

=== 2) 新增“回退到上一个字符边界” helper ===
在 `bicycle_ui_ctl_fit_utf8_width()` 之后新增：

/**
 * @brief 从 n（必须是字符边界）退回上一个 UTF-8 字符边界。
 */
static size_t bicycle_ui_ctl_utf8_prev(const char * s, size_t n)
{
    while (n > 0u) {
        n--;
        if (((unsigned char)s[n] & 0xC0u) != 0x80u) {
            break;
        }
    }

    return n;
}

=== 3) handle_gnss_sim 的文件名 toast 改成“测量高度 + 迭代回退” ===
把当前这段（R4 版本）：
    {
        const char * base = strrchr(path, '/');
        const lv_font_t * font = helm_font_sys(14, helm_font_title());
        const char * prefix = reverse ? "反向回放" : "顺序回放";
        double at_m = bicycle_gpx_sim_prefix_m();
        char tail[24];
        int32_t avail;
        size_t room;

        base = (base != NULL && base[1] != '\0') ? base + 1 : path;
        if (at_m >= 50.0) {
            snprintf(tail, sizeof(tail), " @%.1fkm", at_m / 1000.0);
        } else {
            tail[0] = '\0';
        }

        /* 底部 toast 卡片最大宽 = 屏宽-32，左右内边距各 16 ⇒ 单行 176px；
         * 最多两行，再留 16px 折行余量。扣掉前缀/空格/后缀后才是文件名。 */
        avail = 2 * (lv_pm_hor_res() - 64) - 16;
        if (font != NULL) {
            lv_point_t sz;

            lv_text_get_size(&sz, prefix, font, 0, 0, LV_COORD_MAX,
                             LV_TEXT_FLAG_NONE);
            avail -= (int32_t)sz.x;
            lv_text_get_size(&sz, " ", font, 0, 0, LV_COORD_MAX,
                             LV_TEXT_FLAG_NONE);
            avail -= (int32_t)sz.x;
            if (tail[0] != '\0') {
                lv_text_get_size(&sz, tail, font, 0, 0, LV_COORD_MAX,
                                 LV_TEXT_FLAG_NONE);
                avail -= (int32_t)sz.x;
            }
        }

        /* 文件名再受 toast 缓冲余量限制，避免 snprintf 在 UTF-8 字符中间截断。 */
        room = sizeof(toast) - 1u - strlen(prefix) - 1u - strlen(tail);
        snprintf(toast, sizeof(toast), "%s %.*s%s", prefix,
            (int)bicycle_ui_ctl_fit_utf8_width(base, avail, room), base, tail);
        lv_pm_bottom_show(toast, 0);
    }

改成：
    {
        const char * base = strrchr(path, '/');
        const lv_font_t * font = helm_font_sys(14, helm_font_title());
        const char * prefix = reverse ? "反向回放" : "顺序回放";
        const int32_t line_w = lv_pm_hor_res() - 64;
        double at_m = bicycle_gpx_sim_prefix_m();
        char tail[24];
        int32_t avail;
        size_t room;
        size_t n;

        base = (base != NULL && base[1] != '\0') ? base + 1 : path;
        if (at_m >= 50.0) {
            snprintf(tail, sizeof(tail), " @%.1fkm", at_m / 1000.0);
        } else {
            tail[0] = '\0';
        }

        /* 先用像素宽做粗截：单行 176px，两行 352px，留 16px 折行余量。 */
        avail = 2 * line_w - 16;
        if (font != NULL) {
            lv_point_t sz;

            lv_text_get_size(&sz, prefix, font, 0, 0, LV_COORD_MAX,
                             LV_TEXT_FLAG_NONE);
            avail -= (int32_t)sz.x;
            lv_text_get_size(&sz, " ", font, 0, 0, LV_COORD_MAX,
                             LV_TEXT_FLAG_NONE);
            avail -= (int32_t)sz.x;
            if (tail[0] != '\0') {
                lv_text_get_size(&sz, tail, font, 0, 0, LV_COORD_MAX,
                                 LV_TEXT_FLAG_NONE);
                avail -= (int32_t)sz.x;
            }
        }

        /* 文件名再受 toast 缓冲余量限制，避免 snprintf 在 UTF-8 字符中间截断。 */
        room = sizeof(toast) - 1u - strlen(prefix) - 1u - strlen(tail);
        n = bicycle_ui_ctl_fit_utf8_width(base, avail, room);

        /* 粗截只按总像素宽，遇到空格/换行仍可能排出第三行；这里用 LVGL
         * 自己的折行结果验证高度，超两行就回退一个字符再试。 */
        for (;;) {
            lv_point_t sz;

            snprintf(toast, sizeof(toast), "%s %.*s%s", prefix, (int)n, base,
                     tail);
            if (font == NULL) {
                break;
            }
            lv_text_get_size(&sz, toast, font, 0, 0, line_w,
                             LV_TEXT_FLAG_NONE);
            if (sz.y <= 2 * lv_font_get_line_height(font)) {
                break;
            }
            n = bicycle_ui_ctl_utf8_prev(base, n);
        }
        lv_pm_bottom_show(toast, 0);
    }

检查：
- `grep -n "utf8_prev\|lv_font_get_line_height\|0xF5u\|0xEDu\|0xF4u" bicycle_ui_ctl.c` 能看到新代码。
- `git -C /home/jinsc/SDK/vela/openvela/vendor/my_vendor diff --check`。
- 不构建。

证据：摘要写到
/home/jinsc/SDK/vela/openvela/docs/agent/evidence/WP-PROMPTS/R5/S1/NOTES.md

最终消息只回传：状态、动作、证据路径、首异常、剩余问题、资源释放；不贴大段 diff。

