362	/**
363	 * @brief 解出已校验的 UTF-8 字符码位（len 来自 bicycle_ui_ctl_utf8_len()）。
364	 */
365	static uint32_t bicycle_ui_ctl_utf8_cp(const char * s, size_t len)
366	{
367	    const unsigned char * p = (const unsigned char *)s;
368	
369	    switch (len) {
370	    case 2u:
371	        return ((uint32_t)(p[0] & 0x1Fu) << 6) | (uint32_t)(p[1] & 0x3Fu);
372	    case 3u:
373	        return ((uint32_t)(p[0] & 0x0Fu) << 12) |
374	               ((uint32_t)(p[1] & 0x3Fu) << 6) | (uint32_t)(p[2] & 0x3Fu);
375	    case 4u:
376	        return ((uint32_t)(p[0] & 0x07u) << 18) |
377	               ((uint32_t)(p[1] & 0x3Fu) << 12) |
378	               ((uint32_t)(p[2] & 0x3Fu) << 6) | (uint32_t)(p[3] & 0x3Fu);
379	    default:
380	        return (uint32_t)p[0];
381	    }
382	}
