392	 */
393	static size_t bicycle_ui_ctl_fit_utf8_width(const char * s, int32_t max_w,
394	    size_t max_bytes)
395	{
396	    const lv_font_t * font = helm_font_sys(14, helm_font_title());
397	    size_t n = 0u;
398	    int32_t w = 0;
399	
400	    if (s == NULL || font == NULL || max_w <= 0) {
401	        return 0u;
402	    }
403	
404	    while (s[n] != '\0') {
405	        const size_t len = bicycle_ui_ctl_utf8_len(s, n);
406	        uint32_t cp;
407	        uint32_t next = 0u;
408	        size_t next_len;
409	        int32_t adv;
410	
411	        if (len == 0u || n + len > max_bytes) {
412	            break;
413	        }
414	
415	        cp = bicycle_ui_ctl_utf8_cp(s + n, len);
416	        next_len = bicycle_ui_ctl_utf8_len(s, n + len);
417	        if (next_len != 0u) {
418	            next = bicycle_ui_ctl_utf8_cp(s + n + len, next_len);
419	        }
420	
421	        adv = (int32_t)lv_font_get_glyph_width(font, cp, next);
422	        if (adv > max_w - w) {
423	            break;
424	        }
425	
426	        w += adv;
427	        n += len;
428	    }
429	
430	    return n;
431	}
