        const unsigned char c1 = (unsigned char)s[n + 1u];

        if (c == 0xF0u && c1 < 0x90u) {
            return 0u;          /* 过长 4 字节 */
        }
        if (c == 0xF4u && c1 >= 0x90u) {
            return 0u;          /* > U+10FFFF */
        }
    }

    return len;
}"}

