        { "\xF0\x90\x80\x80", 1 },                  /* U+10000 */
        { "\xC2\x80", 1 },                          /* U+0080 */
        { "\xC0\x80", 0 },                          /* 过长 2 字节 */
        { "\xC1\xBF", 0 },                          /* 过长 2 字节 */
        { "\xE0\x9F\xBF", 0 },                      /* 过长 3 字节 */
        { "\xED\xA0\x80", 0 },                      /* UTF-16 代理区 */
        { "\xED\xBF\xBF", 0 },                      /* UTF-16 代理区 */
        { "\xF0\x8F\xBF\xBF", 0 },                  /* 过长 4 字节 */
        { "\xF4\x90\x80\x80", 0 },                  /* > U+10FFFF */
        { "\xF5\x80\x80\x80", 0 },                  /* F5 首字节 */
        { "\xFF", 0 },
        { "\x80", 0 },                              /* 孤立续字节 */
        { "\xE4", 0 },                              /* 截断 */
        { "\xE4\xB8", 0 },                          /* 截断 */
        { "abc\xE4", 0 },                           /* 合法前缀后截断 */
        { "\xC2", 0 },
        { "\xF0\x9F\x98", 0 },
        { "\xE0\xA0", 0 },
    };
    size_t i;
    int fail = 0;

    for (i = 0u; i < sizeof(cases) / sizeof(cases[0]); i++) {
        int got = valid_string(cases[i].s);

        if (got != cases[i].expect) {
            printf("FAIL case %zu: expect %d got %d\n", i, cases[i].expect,
                   got);
            fail++;
        }
    }

    /* utf8_prev：从 "中文a" 的末尾逐字符回退，必须落在字符边界。 */
    {
        const char * s = "\xE4\xB8\xAD\xE6\x96\x87" "a";
        size_t n = strlen(s);
        size_t steps[4];
        size_t k;

        for (k = 0u; k < 3u; k++) {
            steps[k] = n;
            n = bicycle_ui_ctl_utf8_prev(s, n);
        }
        if (!(steps[0] == 7u && steps[1] == 6u && steps[2] == 3u && n == 0u)) {
            printf("FAIL prev: %zu %zu %zu %zu\n", steps[0], steps[1],
                   steps[2], n);
            fail++;
        }
    }

    if (fail == 0) {
        printf("ALL %zu UTF-8 CASES PASS\n",
               sizeof(cases) / sizeof(cases[0]));
    }

    return fail != 0;
}
"}

